<div class="action-tile-grid"><?php foreach($catalog as $t=>$meta):?><label class="action-tile"><input type="radio" name="type" value="<?=ir_e($t)?>" <?=$t===$presetType?'checked':''?>><span><?=ir_visual_icon((string)$meta['icon'])?><b><?=ir_e($t)?></b></span></label><?php endforeach;?><label class="action-tile"><input type="radio" name="type" value="Vlastní"><span><?=ir_visual_icon('add')?><b>Vlastní</b></span></label></div>
<div class="form-grid cols-2 quick-fields"><label>Datum a čas<input type="datetime-local" name="date" value="<?=ir_e(ir_datetime_input())?>" required></label><label>Vlastní typ<input name="custom_type" placeholder="Použije se jen pro Vlastní"></label><label>Hodnota / krmivo / množství<input name="value" placeholder="volitelné přepsání pro celý výběr"><small class="field-help">U Krmení nech prázdné: každému zvířeti se použije jeho Typ krmení z karty a automaticky se přidá aktuální krok suplementační rotace.</small></label><label>Detail<input name="detail" placeholder="Poznámka, stav, dávka…"></label><label class="b1-check"><input type="checkbox" name="allow_duplicate" value="1" <?=!empty($dupShown)?'':''?>> Povolit opakovaný záznam téhož dne</label><input type="hidden" name="source" value="<?=ir_e(in_array((string)($_GET['source']??''),IR_EVENT_SOURCES,true)?(string)$_GET['source']:'quick')?>"></div></section>
<section class="panel glow-panel"><header class="panel-head"><div><span class="panel-kicker">VÝBĚR</span><h2>Jedinci</h2></div><div class="selection-count" data-selection-count>0 vybráno</div></header><div class="filter-bar"><input type="search" data-animal-filter placeholder="Hledat ID, jméno, druh, ubikaci…"><button type="button" class="btn tiny" data-select-all>Vybrat vše</button><button type="button" class="btn tiny" data-select-none>Zrušit</button></div><div class="select-animal-list" data-animal-list><?php foreach($animals as $a):$photo=ir_asset_photo_url((string)$a['foto']);?><label class="select-animal" data-filter-text="<?=ir_e(strtolower(implode(' ',[(string)$a['jmeno_kod'],(string)$a['latinsky_nazev'],(string)$a['druh'],(string)$a['ubikace_nazev']])) )?>"><input type="checkbox" name="animals[]" value="<?=$a['id']?>" <?=in_array((int)$a['id'],$preselect,true)?'checked':''?>><span class="select-photo"><?php if($photo):?><img src="<?=ir_e($photo)?>" alt=""><?php else:?><?=ir_visual_icon('animals')?><?php endif;?></span><span><strong><?=ir_e((string)$a['latinsky_nazev'])?></strong><small><?=ir_e((string)$a['jmeno_kod'])?> · <?=ir_e((string)($a['ubikace_nazev']??'Bez ubikace'))?></small></span><span class="quick-exception b1-qres" data-feed-only><select name="result[<?=(int)$a['id']?>]" aria-label="Výsledek krmení"><option value="eaten">Snědlo</option><option value="refused">Odmítlo</option><option value="in_shed">Ve svleku</option><option value="not_fed">Nekrmeno</option></select></span></label><?php endforeach;?></div></section>
