<script>addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('form.quick-layout');if(!f)return;const sync=()=>{const t=f.querySelector('input[name=type]:checked')?.value||'';const on=['Krmení','Odmítnutí potravy','Nekrmeno'].includes(t);f.querySelectorAll('[data-feed-only]').forEach(x=>x.hidden=!on);};f.addEventListener('change',sync);sync();});</script>
